<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Biên tập câu hỏi</title><style>
:root{--navy:#172554;--primary:#5149e8;--line:#dce5f3;--muted:#7180a4}*{box-sizing:border-box}body{margin:0;background:#f3f7ff;color:var(--navy);font:15px Segoe UI,Arial}.top{padding:17px max(20px,calc((100% - 1240px)/2));background:#fff;border-bottom:1px solid var(--line);position:sticky;top:0;z-index:5}.top a{color:#4338ca;text-decoration:none;font-weight:800}.crumb{margin-top:7px;color:var(--muted)}.wrap{width:min(1240px,94%);margin:22px auto}.card{background:#fff;border:1px solid var(--line);border-radius:18px;padding:22px;margin-bottom:16px;box-shadow:0 10px 30px #17315c10}.head{display:flex;justify-content:space-between;gap:16px;align-items:center}.head h1{font-size:25px;margin:0 0 5px}.badge{background:#e9edff;color:#4338ca;padding:7px 11px;border-radius:99px;font-weight:800}.grid{display:grid;grid-template-columns:2fr 1fr;gap:14px}label{display:block;font-weight:800;margin:13px 0 6px}input,select,button{width:100%;padding:11px;border:1px solid #cbd7eb;border-radius:10px;font:inherit}button,.btn{background:var(--primary);color:#fff;border:0;font-weight:800;cursor:pointer}.check{display:flex;align-items:center;gap:8px;margin:15px 0}.check input{width:auto}.options{display:grid;gap:10px}.option{display:grid;grid-template-columns:42px minmax(0,1fr) minmax(180px,.55fr) 90px 72px;gap:8px;align-items:center;padding:11px;border:1px solid #e5eaf4;border-radius:13px}.letter{width:38px;height:38px;display:grid;place-items:center;border-radius:10px;background:#edf1ff;color:#4338ca;font-weight:900}.correct{display:flex;gap:6px;align-items:center;font-weight:700;color:#17834d}.correct input{width:auto}.danger{background:#e52b35}.asset-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.asset{border:1px solid var(--line);border-radius:13px;padding:10px}.asset img{width:100%;height:130px;object-fit:contain;background:#f6f8fc;border-radius:9px}.asset small{display:block;overflow:hidden;text-overflow:ellipsis;margin:7px 0;color:var(--muted)}.new-option{margin-top:12px;background:#f7f9ff}.ok,.err{padding:12px 15px;border-radius:10px}.ok{background:#dcfce7;color:#166534}.err{background:#fee2e2;color:#991b1b}.hint{padding:12px;background:#fff8db;border-radius:10px;color:#715807;margin-top:12px}@media(max-width:800px){.grid,.option,.asset-grid{grid-template-columns:1fr}.option{position:relative}.letter{position:absolute;right:10px;top:10px}.head{align-items:flex-start}.wrap{width:calc(100% - 20px)}}
</style></head><body>
