<section class="card"><div class="head"><div><h2>Lựa chọn và đáp án</h2><span class="muted">Đánh dấu “Đáp án đúng”; dạng chọn nhiều có thể đánh dấu nhiều dòng.</span></div><span class="badge">{{ $question->options->count() }} lựa chọn</span></div><div class="options">@foreach($question->options as $option)<form class="option" method="post" action="{{ route('admin.options.update',$option) }}">@csrf @method('put')<span class="letter">{{ chr(65+$loop->index) }}</span><input name="content" value="{{ $option->content }}" placeholder="Nội dung lựa chọn"><input name="image_path" value="{{ $option->image_path }}" placeholder="Ảnh lựa chọn (nếu có)"><label class="correct"><input type="checkbox" name="is_correct" value="1" @checked($option->is_correct)> Đúng</label><input type="hidden" name="position" value="{{ $option->position }}"><button>Lưu</button></form>@endforeach<form class="option new-option" method="post" action="{{ route('admin.options.store',$question) }}">@csrf<span class="letter">＋</span><input name="content" placeholder="Thêm lựa chọn mới"><input name="image_path" placeholder="Ảnh (không bắt buộc)"><label class="correct"><input type="checkbox" name="is_correct" value="1"> Đúng</label><input type="hidden" name="position" value="{{ $question->options->count() }}"><button>Thêm</button></form></div>@if(in_array($question->type,['Hotspot','Matching','Sequence']))<div class="hint">💡 Đây là câu tương tác đặc biệt. Dữ liệu bố cục gốc vẫn được hệ thống bảo toàn tự động; bạn không cần chỉnh JSON.</div>@endif</section>
<section class="card"><div class="head"><div><h2>Hình ảnh và tài nguyên</h2><span class="muted">Xem, thêm hoặc xóa file gắn với câu hỏi.</span></div><span class="badge">{{ $question->assets->count() }} file</span></div><div class="asset-grid">@foreach($question->assets as $asset)<div class="asset">@if($asset->kind==='image')<img src="{{ $asset->path }}" alt="{{ $asset->original_name }}">@else<div class="hint">{{ strtoupper($asset->kind) }}</div>@endif<small>{{ $asset->original_name ?: $asset->path }}</small><form method="post" action="{{ route('admin.assets.destroy',$asset) }}" onsubmit="return confirm('Xóa tài nguyên này?')">@csrf @method('delete')<button class="danger">Xóa file</button></form></div>@endforeach</div><form method="post" enctype="multipart/form-data" action="{{ route('admin.assets.store',$question) }}">@csrf<div class="grid"><div><label>Chọn file mới</label><input type="file" name="file" required></div><div><label>Loại tài nguyên</label><select name="kind"><option value="image">Hình ảnh</option><option value="audio">Âm thanh</option><option value="video">Video</option><option value="document">Tài liệu</option></select></div></div><button style="margin-top:12px">Tải tài nguyên lên</button></form></section>
